  var p = pnt("W" + (i < 9 ? "0" : "") + (i + 1) + " Offset");
  return [p[0], p[1]];
}
// 0 when every row fits inside Max Width. Any positive value
// is the amount the widest row overruns the box by — that row
// is pinned to shift 0 and will stick out.
fitOverflow();

