} else {
  // rows from word count, then balance by measured width
  var want = (nW <= 2) ? 1 : (nW === 3 ? 2 : Math.round(ctl("Rows")));
  want = Math.max(1, Math.min(want, nW));
  var WID = [], sp = ctl("Space W");
  for (var i1 = 0; i1 < nW; i1++) WID[i1] = widthOf(i1);

  function rowW(a, b) {
