// Nothing special handles that case, and nothing needs to:
// stepv is a pure function of the playhead and its own start
// frame, so an unfinished move simply keeps running across the
// boundary. Phases are scheduling labels, not gates.
var TV  = Math.max(0, ctl("T Void"));
var TS  = Math.max(0, ctl("T Seed"));
var TR  = Math.max(0, ctl("T Rack"));
var TSE = Math.max(0, ctl("T Settle"));
var TF  = Math.max(0, ctl("T Fill"));

