var F = ctl("Progress") / 100 * TOTAL;

// ── spawn frames ────────────────────────────────────────
var SPAWN = [];
SPAWN[seed] = pSeed;
if (handoff >= 0) SPAWN[handoff] = pRack;
for (var i5 = 0; i5 < ORD.length; i5++) SPAWN[ORD[i5]] = pFill + i5 * TF;

/**
