function stepv(from, start) {
  if (F < start) return from;
  var s = (from > 0) ? 1 : ((from < 0) ? -1 : 0);
  if (F < start + H)     return s * TA;
  if (F < start + 2 * H) return s * TB;
  return 0;
}

